package com.aicharacter.v3;
import android.content.Context;import org.json.JSONObject;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.X509EncodedKeySpec;import java.util.Base64;
/** Verifies a God-generated visual recipe, checkpoints current content, then installs it as runtime world data. */
public final class SignedGodWorldRecipe{
 private SignedGodWorldRecipe(){}
 public static RuntimeContentUpdater.Result apply(Context c,String payloadB64,String sigB64){try{if(payloadB64==null||sigB64==null)throw new SecurityException("Missing signed recipe");byte[] payload=Base64.getDecoder().decode(payloadB64),sig=Base64.getDecoder().decode(sigB64);if(payload.length>32768)throw new SecurityException("Recipe too large");byte[] kb=Base64.getDecoder().decode(VnfOnlineConfig.CONTENT_PUBLIC_KEY.replaceAll("\\s+",""));PublicKey key=KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(kb));Signature v=Signature.getInstance("SHA256withRSA");v.initVerify(key);v.update(payload);if(!v.verify(sig))throw new SecurityException("God recipe signature invalid");JSONObject j=new JSONObject(new String(payload,StandardCharsets.UTF_8));if(!"visual-profile-v1".equals(j.optString("type")))throw new SecurityException("Unsupported God recipe");JSONObject l=j.getJSONObject("lakeside");checkColor(l.optString("skyTop"));checkColor(l.optString("skyBottom"));checkColor(l.optString("cloud"));RuntimeContentStore.checkpoint(c,"god_visual_recipe");File f=new File(RuntimeContentStore.current(c),"world/visual_profile.json");File p=f.getParentFile();if(p!=null)p.mkdirs();try(FileOutputStream o=new FileOutputStream(f)){o.write(payload);}RuntimeContentStore.touchRevision(c);return new RuntimeContentUpdater.Result(true,"Thần đã áp dụng visual recipe đã ký. Có checkpoint để rollback.");}catch(Throwable t){return new RuntimeContentUpdater.Result(false,"Không áp dụng God recipe: "+t.getMessage());}}
 private static void checkColor(String x){if(x==null||!x.matches("#[0-9A-Fa-f]{6}"))throw new SecurityException("Invalid visual color");}
}
